class Solution {
public:
    string alphabetBoardPath(string target) {
        string res;
        int r = 0, c = 0;
        for (char ch : target) {
            int i = ch - 'a';
            int tr = i / 5, tc = i % 5;
            res.append(max(0, tc - c), 'R');
            res.append(max(0, c - tc), 'L');
            res.append(max(0, tr - r), 'D');
            res.append(max(0, r - tr), 'U');
            res += '!';
            r = tr; c = tc;
        }
        return res;
    }
};

