from collections import deque

class Solution:
    def alphabetBoardPath(self, target: str) -> str:
        def pos(ch):
            i = ord(ch) - ord('a')
            return divmod(i, 5)

        def bfs(sr, sc, tr, tc):
            prev = {(sr, sc): None}
            q = deque([(sr, sc)])
            dirs = [('U', -1, 0), ('D', 1, 0), ('L', 0, -1), ('R', 0, 1)]
            while q:
                r, c = q.popleft()
                if (r, c) == (tr, tc):
                    break
                for m, dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr <= 5 and 0 <= nc < 5 and (nr < 5 or nc == 0) and (nr, nc) not in prev:
                        prev[(nr, nc)] = ((r, c), m)
                        q.append((nr, nc))
            moves = []
            cur = (tr, tc)
            while prev[cur] is not None:
                cur, m = prev[cur]
                moves.append(m)
            return ''.join(reversed(moves))

        res = []
        r = c = 0
        for ch in target:
            tr, tc = pos(ch)
            res.append(bfs(r, c, tr, tc))
            res.append('!')
            r, c = tr, tc
        return ''.join(res)

