class Solution {
public:
    bool valid(int r, int c) { return r < 5 || (r == 5 && c == 0); }

    string bfs(int sr, int sc, int tr, int tc) {
        map<pair<int,int>, pair<pair<int,int>,char>> prev;
        queue<pair<int,int>> q;
        q.push({sr, sc});
        vector<tuple<char,int,int>> dirs = {{'U',-1,0},{'D',1,0},{'L',0,-1},{'R',0,1}};
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            if (r == tr && c == tc) break;
            for (auto& [m, dr, dc] : dirs) {
                int nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr <= 5 && nc >= 0 && nc < 5 && valid(nr, nc) && !prev.count({nr, nc})) {
                    prev[{nr, nc}] = {{r, c}, m};
                    q.push({nr, nc});
                }
            }
        }
        string moves;
        pair<int,int> cur = {tr, tc};
        while (prev.count(cur)) {
            auto [p, m] = prev[cur];
            moves += m;
            cur = p;
        }
        reverse(moves.begin(), moves.end());
        return moves;
    }

    string alphabetBoardPath(string target) {
        string res;
        int r = 0, c = 0;
        for (char ch : target) {
            int i = ch - 'a';
            int tr = i / 5, tc = i % 5;
            res += bfs(r, c, tr, tc);
            res += '!';
            r = tr; c = tc;
        }
        return res;
    }
};

