import java.util.*;

class Solution {
    private boolean valid(int r, int c) { return r < 5 || (r == 5 && c == 0); }

    private String bfs(int sr, int sc, int tr, int tc) {
        Map<Long, long[]> prev = new HashMap<>();
        Deque<long[]> q = new ArrayDeque<>();
        q.add(new long[]{sr, sc});
        char[] ms = {'U', 'D', 'L', 'R'};
        int[][] ds = {{-1,0},{1,0},{0,-1},{0,1}};
        while (!q.isEmpty()) {
            long[] cur = q.poll();
            int r = (int) cur[0], c = (int) cur[1];
            if (r == tr && c == tc) break;
            for (int d = 0; d < 4; d++) {
                int nr = r + ds[d][0], nc = c + ds[d][1];
                long key = nr * 10L + nc;
                if (nr >= 0 && nr <= 5 && nc >= 0 && nc < 5 && valid(nr, nc) && !prev.containsKey(key)) {
                    prev.put(key, new long[]{r, c, ms[d]});
                    q.add(new long[]{nr, nc});
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        long key = tr * 10L + tc;
        while (prev.containsKey(key)) {
            long[] p = prev.get(key);
            sb.append((char) p[2]);
            key = p[0] * 10L + p[1];
        }
        return sb.reverse().toString();
    }

    public String alphabetBoardPath(String target) {
        StringBuilder res = new StringBuilder();
        int r = 0, c = 0;
        for (char ch : target.toCharArray()) {
            int i = ch - 'a';
            int tr = i / 5, tc = i % 5;
            res.append(bfs(r, c, tr, tc));
            res.append('!');
            r = tr; c = tc;
        }
        return res.toString();
    }
}

