var alphabetBoardPath = function(target) {
    const valid = (r, c) => r < 5 || (r === 5 && c === 0);
    const bfs = (sr, sc, tr, tc) => {
        const prev = new Map();
        const key = (r, c) => r * 10 + c;
        const q = [[sr, sc]];
        const dirs = [['U',-1,0],['D',1,0],['L',0,-1],['R',0,1]];
        while (q.length) {
            const [r, c] = q.shift();
            if (r === tr && c === tc) break;
            for (const [m, dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr <= 5 && nc >= 0 && nc < 5 && valid(nr, nc) && !prev.has(key(nr, nc))) {
                    prev.set(key(nr, nc), [key(r, c), m]);
                    q.push([nr, nc]);
                }
            }
        }
        let moves = '';
        let k = key(tr, tc);
        while (prev.has(k)) {
            const [pk, m] = prev.get(k);
            moves = m + moves;
            k = pk;
        }
        return moves;
    };
    let res = [];
    let r = 0, c = 0;
    for (const ch of target) {
        const i = ch.charCodeAt(0) - 97;
        const tr = Math.floor(i / 5), tc = i % 5;
        res.push(bfs(r, c, tr, tc));
        res.push('!');
        r = tr; c = tc;
    }
    return res.join('');
};
